CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),phone text UNIQUE NOT NULL CHECK(phone ~ '^\+91[6-9][0-9]{9}$'),name text NOT NULL DEFAULT '',language text NOT NULL DEFAULT 'en' CHECK(language IN ('en','ml')),suspended boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE user_roles(user_id uuid REFERENCES users(id),role text CHECK(role IN ('PASSENGER','DRIVER','BUS_CREW','OPERATOR','ADMIN')),PRIMARY KEY(user_id,role));
CREATE TABLE passenger_profiles(user_id uuid PRIMARY KEY REFERENCES users(id));
CREATE TABLE driver_profiles(user_id uuid PRIMARY KEY REFERENCES users(id),verification text NOT NULL DEFAULT 'PENDING' CHECK(verification IN ('PENDING','APPROVED','REJECTED','SUSPENDED')),online boolean NOT NULL DEFAULT false);
CREATE TABLE operators(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,verified boolean NOT NULL DEFAULT false);
CREATE TABLE operator_members(operator_id uuid REFERENCES operators(id),user_id uuid REFERENCES users(id),PRIMARY KEY(operator_id,user_id));
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),access_hash text UNIQUE NOT NULL,refresh_hash text UNIQUE NOT NULL,access_expires timestamptz NOT NULL,refresh_expires timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false);
CREATE TABLE used_refresh_tokens(hash text PRIMARY KEY,session_id uuid NOT NULL REFERENCES sessions(id),expires_at timestamptz NOT NULL);
CREATE TABLE otp_challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),phone text NOT NULL,code_hash text NOT NULL,expires_at timestamptz NOT NULL,attempts integer NOT NULL DEFAULT 0,consumed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX otp_phone_created ON otp_challenges(phone,created_at);
CREATE TABLE rate_limits(key text PRIMARY KEY,window_start timestamptz NOT NULL,count integer NOT NULL);
CREATE TABLE consent_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),version text NOT NULL,accepted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE device_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),token text UNIQUE NOT NULL,platform text CHECK(platform IN ('android','ios')),updated_at timestamptz DEFAULT now());
CREATE TABLE data_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('EXPORT','DELETE')),status text NOT NULL DEFAULT 'PENDING',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vehicles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operator_id uuid REFERENCES operators(id),driver_id uuid REFERENCES users(id),registration text UNIQUE NOT NULL,category text CHECK(category IN ('BUS','AUTO','TAXI')),capacity integer NOT NULL CHECK(capacity>0),approved boolean NOT NULL DEFAULT false);
CREATE TABLE driver_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),driver_id uuid REFERENCES driver_profiles(user_id),kind text NOT NULL,object_key text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'PENDING',expires_at date);
CREATE TABLE vehicle_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vehicle_id uuid REFERENCES vehicles(id),kind text NOT NULL,object_key text UNIQUE NOT NULL,expires_at date,status text NOT NULL DEFAULT 'PENDING');
CREATE TABLE bus_routes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operator_id uuid NOT NULL REFERENCES operators(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE route_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),route_id uuid NOT NULL REFERENCES bus_routes(id),version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(route_id,version));
CREATE TABLE bus_stops(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operator_id uuid NOT NULL REFERENCES operators(id),name text NOT NULL,point geography(Point,4326) NOT NULL);
CREATE INDEX stops_spatial ON bus_stops USING gist(point);
CREATE TABLE route_stops(route_version_id uuid REFERENCES route_versions(id),stop_id uuid REFERENCES bus_stops(id),sequence integer CHECK(sequence>=0),offset_minutes integer CHECK(offset_minutes>=0),PRIMARY KEY(route_version_id,sequence),UNIQUE(route_version_id,stop_id));
CREATE TABLE service_calendars(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operator_id uuid REFERENCES operators(id),start_date date NOT NULL,end_date date NOT NULL,weekdays integer[] NOT NULL,CHECK(end_date>=start_date));
CREATE TABLE scheduled_trips(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),route_version_id uuid NOT NULL REFERENCES route_versions(id),calendar_id uuid REFERENCES service_calendars(id),departure_local time NOT NULL,timezone text NOT NULL DEFAULT 'Asia/Kolkata');
CREATE TABLE trip_exceptions(scheduled_trip_id uuid REFERENCES scheduled_trips(id),service_date date,kind text CHECK(kind IN ('ADDED','REMOVED')),PRIMARY KEY(scheduled_trip_id,service_date));
CREATE TABLE trip_instances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scheduled_trip_id uuid REFERENCES scheduled_trips(id),operator_id uuid NOT NULL REFERENCES operators(id),route_version_id uuid NOT NULL REFERENCES route_versions(id),vehicle_id uuid NOT NULL REFERENCES vehicles(id),service_date date NOT NULL,departure_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'SCHEDULED' CHECK(status IN ('SCHEDULED','BOARDING','RUNNING','DELAYED','STOPPED','BREAKDOWN','DIVERTED','CANCELLED','COMPLETED')),delay_minutes integer NOT NULL DEFAULT 0 CHECK(delay_minutes BETWEEN 0 AND 720),version integer NOT NULL DEFAULT 1,UNIQUE(scheduled_trip_id,service_date));
CREATE TABLE driver_assignments(trip_id uuid REFERENCES trip_instances(id),user_id uuid REFERENCES users(id),duty text NOT NULL CHECK(duty IN ('DRIVER','CONDUCTOR')),PRIMARY KEY(trip_id,user_id));
CREATE TABLE vehicle_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vehicle_id uuid REFERENCES vehicles(id),trip_id uuid REFERENCES trip_instances(id),assigned_at timestamptz NOT NULL DEFAULT now(),UNIQUE(trip_id,vehicle_id));
CREATE TABLE vehicle_locations(trip_id uuid PRIMARY KEY REFERENCES trip_instances(id),point geography(Point,4326) NOT NULL,accuracy_m integer NOT NULL CHECK(accuracy_m BETWEEN 0 AND 100),recorded_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX locations_spatial ON vehicle_locations USING gist(point);
CREATE TABLE vehicle_location_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,trip_id uuid REFERENCES trip_instances(id),point geography(Point,4326) NOT NULL,recorded_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX location_history_time ON vehicle_location_history(received_at);
CREATE TABLE service_incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid REFERENCES trip_instances(id),actor_id uuid REFERENCES users(id),kind text NOT NULL,reason text NOT NULL,delay_minutes integer,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id uuid REFERENCES users(id),operator_id uuid REFERENCES operators(id),action text NOT NULL,resource_id uuid,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,topic text NOT NULL,resource_id uuid NOT NULL,version integer NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_resource ON events(resource_id,id);
CREATE TABLE notification_subscriptions(user_id uuid REFERENCES users(id),trip_id uuid REFERENCES trip_instances(id),PRIMARY KEY(user_id,trip_id));
CREATE TABLE notifications(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id uuid REFERENCES users(id),event_id bigint REFERENCES events(id),status text NOT NULL DEFAULT 'PENDING',attempts integer NOT NULL DEFAULT 0,next_attempt timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_id));
CREATE TABLE idempotency_keys(actor_id uuid REFERENCES users(id),key text,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,key));
